input.command:
python3 -I - <<'EOF'
from PIL import Image, ImageChops
import os, glob
for d in sorted(glob.glob('visual-report/images/*')):
    b=Image.open(os.path.join(d,'baseline.png')).convert('RGB')
    c=Image.open(os.path.join(d,'current.png')).convert('RGB')
    print(os.path.basename(d), b.size, c.size, end=' ')
    if b.size!=c.size:
        print('SIZE DIFF'); continue
    diff=ImageChops.difference(b,c).convert('L')
    px=diff.load(); w,h=diff.size
    n=0; minx=w; miny=h; maxx=0; maxy=0
    rows={}
    for y in range(h):
        for x in range(w):
            if px[x,y]>16:
                n+=1; minx=min(minx,x); maxx=max(maxx,x); miny=min(miny,y); maxy=max(maxy,y)
                rows[y]=rows.get(y,0)+1
    print('diffpx',n, 'bbox', (minx,miny,maxx,maxy) if n else None)
EOF

