cat > "$TMPDIR/check.js" <<'EOF'
const { chromium } = require('/var/tmp/avb-runs/avb-iSIUvp/project/node_modules/@playwright/test');
const fs = require('fs');
const path = require('path');
const root = '/var/tmp/avb-runs/avb-iSIUvp/project';
const pages = {home:'/',products:'/products.html',pricing:'/pricing.html',orders:'/orders.html',contact:'/contact.html',about:'/about.html'};
const sizes = {desktop:{width:1280,height:800},phone:{width:390,height:844}};
function norm(h){return h.replace(/>\s+</g,'><').replace(/\s+/g,' ').trim();}
(async()=>{
 const browser=await chromium.launch();
 for (const [size,viewport] of Object.entries(sizes)) {
  const ctx=await browser.newContext({viewport,deviceScaleFactor:1});
  for (const [name,url] of Object.entries(pages)) {
   const key=name+'__'+size;
   const base=fs.readFileSync(path.join(root,'.testivai/baselines',key,'dom.html'),'utf8');
   const page=await ctx.newPage();
   await page.goto('http://127.0.0.1:'+ (process.env.PORT||4173) + url);
   await page.evaluate(()=>document.fonts.ready);
   const cur=await page.evaluate(()=>document.documentElement.outerHTML);
   const a=norm(base), b=norm(cur);
   let same=a===b;
   let detail='';
   if(!same){
     // find first difference
     let i=0; while(i<a.length&&i<b.length&&a[i]===b[i]) i++;
     detail=` firstdiff@${i}\n  base: ...${a.slice(Math.max(0,i-80),i+120)}\n  cur : ...${b.slice(Math.max(0,i-80),i+120)}`;
   }
   console.log(key, same?'DOM IDENTICAL':'DOM DIFFERS', detail);
   await page.close();
  }
  await ctx.close();
 }
 await browser.close();
})();
EOF
